      "id": "p-0003",
      "sectionId": "act-1",
      "fr": "ROSE, DANIEL : (Ils lisent des articles de journaux.) - DANIEL Tu as lu celui-là ?",
      "en": "ROSE, DANIEL: (Ils lisent des articles de journaux.) - DANIEL Have you read this one?"
